// ProductCardGlass.jsx
import React from "react";
import styled, { css } from "styled-components";
const CSS = css;
// image variable
// const zen =
// "https://images.unsplash.com/photo-1508672019048-805c876b67e2?auto=format&fit=crop&w=793&q=80";
const zen = "/architecture_details.png";
// Styled Components
// Styled Components shared styles
const sharedStyles = CSS` 
  ${(props) => props.isFlex && flexStyles};
  ${(props) => props.hover && activeStyles};
  position: ${(props) => props.position};
  top: ${(props) => props.top};
  bottom: ${(props) => props.bottom};
  right: ${(props) => props.right};
  left: ${(props) => props.left};
  width: ${(props) => props.width};
  height: ${(props) => props.height};
  background: ${(props) => props.background};
  transform: ${(props) => props.transform};
  transition: ${(props) => props.transition};
  z-index: ${(props) => props.zIndex};
  opacity: ${(props) => props.opacity};
  cursor: ${(props) => props.cursor};
  padding: ${(props) => props.padding || "0px"};
  margin: ${(props) => props.margin || "0px"};
  border: ${(props) => props.border || "none"};
  border-radius: ${(props) => props.borderRadius || "none"};
  box-shadow: ${(props) => props.boxShadow || "none"};
  color: ${(props) => props.color};
  backdrop-filter: ${(props) => props.backdropFilter};
  background-image: ${(props) => props.backgroundImage};
  background-repeat: ${(props) => props.backgroundRepeat};
  background-attachment: ${(props) => props.backgroundAttachment};
  background-position: ${(props) => props.backgroundPosition};
  background-size: ${(props) => props.backgroundSize};
  backface-visibility: ${(props) => props.backfaceVisibility};  
  
  `;

// Styled Components flex styles
const flexStyles = CSS`
  display: flex;
  flex-direction: ${(props) => props.flexDirection || "row"};
  align-items: ${(props) => props.alignItems || "start"};
  justify-content: ${(props) => props.justifyContent || "start"};
`;

//Styled Components active styles
const activeStyles = CSS`
  ${(props) =>
    props.hover
      ? "&:hover .productCardGlass__card__blur__front {transform: rotateY(180deg); }"
      : null}
  ${(props) =>
    props.hover
      ? "&:hover .productCardGlass__card__blur__back {transform: rotateY(0); width: 100%; height: 100%; opacity: 1;  }"
      : null}
`;

// Styled Components shared typography styles
const sharedTypography = CSS`
  ${sharedStyles};
  color: ${(props) => props.color};
  text-decoration: ${(props) => props.textDecoration};
  text-align: ${(props) => props.textAlign};
  font-size: ${(props) => props.fontSize};
`;

// Styled-Component div
const StyledWrapper = styled.div`
  ${sharedStyles};
  ${(props) => props.isFlex && flexStyles};
`;

// Styled-Component h1
const StyledTitle = styled.h1`${sharedTypography} ${sharedStyles}`;

// Styled-Component h2
const StyledSubTitle = styled.h3`${sharedTypography} ${sharedStyles}`;

// Styled-Component p
const StyledP = styled.p`${sharedTypography} ${sharedStyles}`;

// Styled-Component img
const StyledImg = styled.img`
  ${sharedStyles};
  object-fit: cover;
`;

// rename and build your component
function ProductCardGlass({
  width,
  height,
  imgWidth,
  imgHeight,
  fontSize,
  cursor,
  transition,
  primaryColor,
  secondaryColor,
  buttonBackground,
  buttonHeight,
  border,
  cardBackground
}) {
  return (
    <StyledWrapper className="productCardGlass">
      <StyledWrapper
        className="productCardGlass__card"
        isFlex
        justifyContent="center"
        alignItems="center"
        width={width}
        height={height}
        // background="rgba(255,255,255,0.4)"
        backgroundImage={`url(${zen})`}
        backgroundPosition="center"
        backgroundSize="cover"
        backgroundRepeat="no-repeat"
        position="relative"
        borderRadius="0.5rem"
        boxShadow="0 20px 50px rgba(0,0,0,0.89)"
        hover
      >
        <StyledWrapper
          className="productCardGlass__card__blur__front"
          isFlex
          flexDirection="column"
          justifyContent="center"
          alignItems="center"
          position="absolute"
          width={"60%"}
          height={"60%"}
          background="rgba(255,255,255,0.2)"
          backdropFilter="blur(5px)"
          margin="1rem"
          borderRadius="0.5rem"
          transition="all 0.8s ease"
          backfaceVisibility="hidden"
          cursor={cursor}
        >
          <StyledSubTitle color="rgba(0,0,0,0.89)" padding=".25rem 0">
            @learnMern
          </StyledSubTitle>
          <StyledP color="rgba(0,0,0,0.6)">React Developer</StyledP>
        </StyledWrapper>
        <StyledWrapper
          className="productCardGlass__card__blur__back"
          isFlex
          flexDirection="column"
          justifyContent="center"
          alignItems="center"
          position="absolute"
          width="50%"
          height="30%"
          background="#404040"
          backdropFilter="blur(5px)"
          margin="1rem"
          borderRadius="0.5rem"
          transition="all 0.8s ease"
          backfaceVisibility="hidden"
          cursor={cursor}
          transform="rotateY(-180deg)"
          opacity="0"
          border={`1px solid rgba(255,255,255, .1)`}
        >
          <StyledWrapper
            className="productCardGlass__card__blur__back__content"
            isFlex
            flexDirection="column"
            justifyContent="space-evenly"
            height="80%"
            width="80%"
          >
            <StyledSubTitle color={primaryColor} padding="1rem 0">
              React Developer
            </StyledSubTitle>
            <StyledP fontSize="0.75rem" color={secondaryColor}>
              Lorem ipsum dolor sit amet, verear fabellas corrumpit vix no, ne
              has omnis sanctus sensibus, prima nihil meliore ad per. Est cu
              qualisque persecuti. Autem imperdiet gubergren sed ne, an.
            </StyledP>
          </StyledWrapper>
        </StyledWrapper>
      </StyledWrapper>
    </StyledWrapper>
  );
}

// default props
ProductCardGlass.defaultProps = {
  width: "300px",
  height: "200px",
  imgWidth: "80px",
  imgHeight: "80px",
  fontSize: "0.75rem",
  cursor: "pointer",
  transition: "0.5s",
  primaryColor: "rgba(255,255,255,.89)",
  secondaryColor: "rgba(255,255,255,.6)",
  cardBackground: "#404040",

  buttonBackground: "linear-gradient(315deg, #7f5a83 0%, #0d324d 95%)",
  buttonHeight: "2rem",
  border: "1px solid #7f5a83",
  body:
    "Lorem ipsum dolor sit amet, verear fabellas corrumpit vix no, ne has omnis sanctus sensibus, prima nihil meliore ad per. Est cu qualisque persecuti. Autem imperdiet gubergren sed ne, an."
};


export default ProductCardGlass;
